// AllSchemes returns all available color schemes (built-in + community).
func AllSchemes() []ColorScheme {
	all := make([]ColorScheme, 0, len(BuiltInSchemes)+len(CommunitySchemes))
	all = append(all, BuiltInSchemes...)
	all = append(all, CommunitySchemes...)
	return all
}
